"""Evidence-linked light/dark review; passing tests do not invent visual acceptance."""
import collections,hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[1];out=root/'artifacts';captures=out/'screenshots'
results=[json.loads(line) for line in (root/'build/meson-logs/testlog.json').read_text().splitlines()]
counts=collections.Counter(x['result'] for x in results);assert counts.get('FAIL',0)==0 and counts.get('ERROR',0)==0,counts
lines=['# Visual conformance report — 2026-10-09','','Reviewed uncropped native frames and separately captured complete popups/tooltip surfaces against the unchanged HTML authorities. PASS concerns exposed theme styling; native structure and GNOME compositor acceptance remain separately classified.','',f'Meson: {dict(counts)}. Exact Plus Jakarta Sans required; no font skips.','']
for variant,file in [('light','visual-review.json'),('dark','visual-review-dark.json')]:
 review=json.loads((root/'docs'/file).read_text());meta=json.loads((captures/variant/'capture-metadata.json').read_text())
 ref=json.loads((captures/('html-dark' if variant=='dark' else 'html')/'render-metadata.json').read_text())
 assert hashlib.sha256((root/ref['source']).read_bytes()).hexdigest()==ref['sha256']
 lines+=['## '+variant.upper(),'',f'Native: 1440×1080 Xvfb, scale 1, Cairo, Openbox/xcompmgr; requested/resolved font {meta["font_resolved"]}. Reference SHA256 `{ref["sha256"]}`. Temporary local normal/italic font injection only.','',f'[HTML authority](screenshots/{"html-dark" if variant=="dark" else "html"}/full-reference.png) · [Capture metadata](screenshots/{variant}/capture-metadata.json)','','| Category | Evidence | Result | Observation / classification |','|---|---|---|---|']
 for section,image,status,reason in review['rows']:
  assert status in ('PASS','PARTIAL — native constraint','FAIL','NOT VALIDATABLE UNDER WSL')
  assert (captures/variant/image).is_file(),image
  lines.append(f'| {section} | [{image}](screenshots/{variant}/{image}) | {status} | {reason} |')
comparison=json.loads((out/'final-fixes-baseline-comparison.json').read_text())
lines+=['','## SURGICAL CONFORMANCE FIXES','', 'Baseline: 28/28 passed, preserved before edits under baseline-final-fixes. Final clean build: '+str(len(results))+'/'+str(len(results))+' passed, no skips. Debian 13.5 Trixie / GTK3 3.24.49 / GTK4 4.18.6 / libadwaita 1.7.6.','', '| Issue | Result | Evidence |','|---|---|---|', '| Dark palette alias integrity | RESOLVED | Primitive p50–p800 remain canonical in both GTK versions; negative p700 corruption test fails independently of semantic hover. |', '| Dark indeterminate checkbox | RESOLVED | p600 #4F46E5 appears in actual native GTK3/4 light/dark checkboxes; six states captured in checkbox-probes. |', '| GTK4 outer window edge | RESOLVED for exposed edge; compositor acceptance pending | Native pixel validation proves a single 1px edge: light rgba(20,20,25,.12), dark rgba(255,255,255,.07). The inherited libadwaita outline is suppressed. Max/full frames have square seamless corners and zero inset. |', '| Window-control focus interpretation | RESOLVED | Transparent reserved border + external 2px .24 light / .36 dark halo; no regular shadow; exact plates/glyphs. |', '| Majoris app symbolic-icon audit | COMPLETED; owning-app fixes remain separate | Read-only scan: 20 SVGs, six likely fixed-paint symbolic bugs in Clock/Calculator; theme glyphs use currentColor, spinner paints intentional. |','', '[Symbolic audit](symbolic-icon-audit.md) · [Every primary-index reference](dark-primary-reference-audit.md) · [Native edge pixels](window-edge-pixel-validation.json) · [Native managed states and restore geometry](window-edge-probes/geometry.json)','', 'Canonical p500 #6366F1, p600 #4F46E5, p700 #4338CA, p800 #3730A3. Dark semantic actions: primary #6366F1 / #7377F3 / #4F46E5; focus #818CF8; danger #DC3C4D / #E34B5B / #B92F3E. Mixed checkbox remains #4F46E5, independently of focus.','', '## BASELINE COMPARISON','']
for variant in ('light','dark'):
 rows=[x for x in comparison if x['variant']==variant]
 lines.append(variant.title()+': '+str(sum(x['status']=='identical' for x in rows))+' identical, '+str(sum(x['status']=='changed' for x in rows))+' changed complete images, '+str(sum(x['status']=='new diagnostic' for x in rows))+' new diagnostic frames.')
lines+=['', 'GTK4 adds the required 1px client edge on each side; the fixed outer window size therefore reserves 2px total and shifts interior origins by 1px. Internal header/control heights do not change. Dark mixed marks change from #818CF8 to #4F46E5; dark focused title buttons lose the incorrect inner edge. GTK3 edge paints now use the exact authority instead of neutral token approximations. Spinner assets are unchanged. Unrelated source styling remains stable. Root XWD captures have pre-existing black transparent-corner pixels and clip exterior CSD shadows; those compositor effects require GNOME acceptance and are not a complete conformance claim.', '', '[Full-frame pixel comparison](final-fixes-baseline-comparison.json) · [18-item implementation audit](../docs/surgical-conformance.md) · [Exact changed files](../docs/surgical-changed-files.txt)','', '## SHARED GEOMETRY','']
l=json.loads((out/'geometry-light.json').read_text());d=json.loads((out/'geometry-dark.json').read_text());assert l==d
lines+=['The entire realized widget tree, font and geometry reports are identical between variants. Hidden banners remain 0px.','', '| Fixture | Header | Content | Divider | Window control / glyph |','|---|---:|---:|---:|---|']
for name in ('simple_headerbar','dense_headerbar','split_sidebar_headerbar','split_content_headerbar'):
 h=l[name];lines.append(f'| {name} | {h["allocation_height"]} | {h["content_height"]} | {h["divider"]} | 32×32 / 16×16 |')
lines+=['','[Light geometry](geometry-light.json) · [Dark geometry](geometry-dark.json) · [Native live/system switching](variant-switching.json) · [Dark contrast](dark-contrast.json)','', '## TOOLKIT CONSTRAINTS','','NATIVE TOOLKIT CONSTRAINT: Adw preference-row internals, ViewSwitcher icon/content structure, popover arrow and accelerator layout, Banner positioning, Toast adaptive width and close control, AlertDialog response layout, native tooltip arrow differences, overlay-scrollbar allocation and GTK3 solid-CSD fallback decorations cannot exactly duplicate the simulated HTML layout. The exposed palette, radii, shadows and state treatment are implemented. Six Clock/Calculator fixed-paint symbolic resources are flagged for owning-app review; no sibling application assets were modified.','', '## VM-ONLY VALIDATION','','GNOME SESSION VALIDATION REQUIRED: Settings produced no visible window; blank output was rejected. Shell styles pass both static grammar/selector suites, but User Themes/automatic switching, St rendering, panel, Quick Settings, calendar, notifications, search/overview/dash, Mutter shadows/corners, inactive/maximized/restored/tiled windows, fractional scaling, Wayland, portals and GDM require the target GNOME VM.','', '[Implementation and switching](../docs/dark-theme.md) · [17-item completion audit](../docs/dark-theme-completion.md) · [Exact changed files](../docs/dark-changed-files.txt)','']
(out/'visual-conformance-report.md').write_text('\n'.join(lines));print('Generated light/dark visual conformance report')
